<?php require __DIR__.'/bootstrap.php'; require_login();
$notices=$pdo->query('SELECT n.*,u.name author FROM notices n JOIN users u ON u.id=n.author_id ORDER BY published_at DESC LIMIT 6')->fetchAll();
$events=$pdo->query("SELECT * FROM events WHERE starts_at>=datetime('now') ORDER BY starts_at LIMIT 5")->fetchAll();
$classes=$pdo->prepare('SELECT * FROM timetable_entries WHERE user_id=? ORDER BY day_of_week,starts_at'); $classes->execute([user()['id']]); $classes=$classes->fetchAll(); page_top('Dashboard'); ?>
<div class="hero"><div><p class="eyebrow">Welcome back</p><h1><?=e(user()['name'])?></h1><p><?=e(user()['course'] ?: 'Student')?></p></div><button class="secondary" data-theme-toggle>Toggle theme</button></div>
<section class="grid three"><article class="stat"><b><?=count($notices)?></b><span>Recent notices</span></article><article class="stat"><b><?=count($events)?></b><span>Upcoming events</span></article><article class="stat"><b><?=count($classes)?></b><span>Weekly classes</span></article></section>
<section class="grid two"><div class="panel"><h2>Notices</h2><?php foreach($notices as $n): ?><article class="item"><h3><?=e($n['title'])?></h3><p><?=e($n['body'])?></p><small><?=e($n['author'])?> - <?=date('d M Y',strtotime($n['published_at']))?></small></article><?php endforeach; if(!$notices) echo '<p class="muted">No notices yet.</p>'; ?></div><div class="panel"><h2>Upcoming events</h2><?php foreach($events as $x): ?><article class="item"><h3><?=e($x['title'])?></h3><p><?=date('D, d M Y H:i',strtotime($x['starts_at']))?><?= $x['location'] ? ' · '.e($x['location']) : '' ?></p></article><?php endforeach; if(!$events) echo '<p class="muted">No upcoming events.</p>'; ?></div></section>
<section class="panel"><h2>My timetable</h2><div class="table-wrap"><table><thead><tr><th>Day</th><th>Time</th><th>Subject</th><th>Room</th></tr></thead><tbody><?php foreach($classes as $c): ?><tr><td><?=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][$c['day_of_week']-1]?></td><td><?=substr($c['starts_at'],0,5)?> - <?=substr($c['ends_at'],0,5)?></td><td><?=e($c['subject'])?></td><td><?=e($c['room'])?></td></tr><?php endforeach; ?></tbody></table></div></section><?php page_bottom();
